"""Build a self-contained animated explorer from the retained integer witnesses."""
from pathlib import Path
import json

ROOT=Path(__file__).resolve().parents[2]
bundle=json.loads((ROOT/'src/ebllm/construct/data/seed_top346.json').read_text())
template=r'''<!doctype html>
<html lang="en"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1">
<title>Anaxia | finite interval certificates</title>
<style>
:root{color-scheme:dark;--bg:#080e1c;--panel:#111b30;--line:#29384f;--ink:#edf4ff;--muted:#adbbce;--mint:#62e9c8;--red:#ff8c9d;--blue:#9eb4ff}*{box-sizing:border-box}body{margin:0;background:radial-gradient(ellipse at 80% 0,#1b2551,var(--bg) 60%);color:var(--ink);font:16px/1.6 system-ui,sans-serif}main{max-width:1250px;margin:auto;padding:40px 28px}header p{max-width:840px;color:var(--muted)}h1{font-size:clamp(30px,5vw,52px);line-height:1.1;letter-spacing:-1.7px;margin:12px 0 20px}h2{font-size:20px;margin-top:0}.eyebrow{color:var(--mint);letter-spacing:3px;font-size:12px;text-transform:uppercase}.metrics{display:grid;grid-template-columns:repeat(4,1fr);gap:12px;margin:26px 0}.metric,.panel{background:var(--panel);border:1px solid var(--line);border-radius:18px;padding:22px}.metric b{font-size:30px;display:block}.metric span{color:var(--muted);font-size:13px}.grid{display:grid;grid-template-columns:1.25fr 1fr;gap:16px}.panel{min-width:0}button,select{background:#1d2c48;color:var(--ink);border:1px solid #4a6080;border-radius:8px;padding:10px;font:inherit;cursor:pointer}button:hover{border-color:var(--mint)}button:focus-visible,select:focus-visible{outline:2px solid var(--mint)}.tools{display:flex;gap:10px;flex-wrap:wrap;margin-bottom:14px}label{color:var(--muted);font-size:13px}canvas{width:100%;height:370px;display:block;border:1px solid var(--line);border-radius:12px;background:#0a1222}.legend{display:flex;gap:18px;font-size:13px;margin:12px 0;color:var(--muted)}code{color:var(--mint);font:13px ui-monospace,monospace;overflow-wrap:anywhere}table{width:100%;border-collapse:collapse;font-size:13px;white-space:nowrap}th,td{text-align:right;padding:9px 6px;border-bottom:1px solid var(--line)}th:first-child,td:first-child{text-align:left}tr[data-i]{cursor:pointer}tr[aria-selected=true]{background:#223753}tr[data-i]:hover{background:#1b2c45}.scroll{overflow:auto}.formula{font:19px/1.8 ui-serif,Georgia,serif;padding:18px 0;color:var(--mint)}.bar{height:18px;background:#172540;border-radius:3px;position:relative;margin:12px 0 27px}.bar span{display:block;height:100%;background:linear-gradient(90deg,#6485ff,var(--mint));border-radius:3px;transition:width 800ms cubic-bezier(.2,.8,.2,1)}.bar em{position:absolute;top:20px;left:0;color:var(--muted);font-size:12px;font-style:normal}.detail{display:grid;grid-template-columns:1fr 1fr;gap:12px}.detail b{display:block;font-size:21px}.detail small{color:var(--muted)}details{margin-top:18px}pre{white-space:pre-wrap;font:12px/1.7 ui-monospace,monospace;max-height:210px;overflow:auto;color:var(--muted)}footer{padding:24px 0;color:var(--muted);font-size:13px}input[type=range]{width:180px;accent-color:var(--mint)}.note{border-left:3px solid var(--mint);padding-left:16px;color:var(--muted);font-size:14px}@media(max-width:900px){.grid{grid-template-columns:1fr}.metrics{grid-template-columns:repeat(2,1fr)}main{padding:28px 16px}}@media(prefers-reduced-motion:reduce){*{transition:none!important}}
</style>
<main><header><div class="eyebrow">Anaxia / exact integer geometry / research revision</div>
<h1>From a cut to a certified descent.</h1><p>Twelve explicit subpolytopes improve the maximum shortest reflexive-descent bound to 346, relative to the supplied Kreuzer–Skarke census. Explore the actual four-dimensional lattice points, the cuts and the interval proof.</p></header>
<div class="metrics"><div class="metric"><b>≤ 346</b><span>maximum shortest descent</span></div><div class="metric"><b>12 / 12</b><span>integer witnesses checked</span></div><div class="metric"><b>473,800,776</b><span>polytopes in the supplied census</span></div><div class="metric"><b>348</b><span>unchanged bound for every descent</span></div></div>
<div class="grid"><section class="panel"><h2>Rotate the exact point cloud</h2><div class="tools"><select id="case" aria-label="Certificate"></select><button id="play">Pause rotation</button><button id="next">Next certificate</button><button id="download">Download data</button></div><canvas id="cloud" aria-label="Animated orthogonal projection of four-dimensional lattice points"></canvas><div class="legend"><span style="color:var(--mint)">● retained in Q</span><span style="color:var(--red)">● removed by the cut</span></div><div class="tools"><label>Discarded-point opacity <input type="range" id="opacity" min="0" max="1" value="0.25" step="0.05"></label></div><code id="cut"></code><p id="hover" style="min-height:26px;color:var(--muted);font-size:13px">Hover over a projected point for its four integer coordinates.</p><p class="note">This is a rotating 2D projection of 4D coordinates, not a 3D polytope or an intermediate chain. The cut is exact; the animation does not assert that it is a cover.</p></section>
<section class="panel"><h2>The proof budget</h2><div class="formula">δ(P) ≤ c(P,Q) + L(Q)<br>c = min{ℓ(P) − ℓ(Q), ℓ(Q*) − ℓ(P*)}</div><div class="detail" id="detail"></div><div class="bar"><span id="bar"></span><em id="barlabel"></em></div><ol style="padding-left:22px;color:var(--muted)"><li>The interval [Q,P] is finite: every member is the hull of a subset of P's lattice points.</li><li>A maximal chain in this interval consists of genuine covers. Each step loses a primal point and gains a polar point, so it costs at most c.</li><li>Concatenate with a descent of Q, bounded by the independently recomputed pair-chain value L(Q).</li></ol><details><summary>Exact source vertices and provenance</summary><pre id="vertices"></pre></details></section></div>
<section class="panel" style="margin-top:16px"><h2>All twelve exceptional census entries</h2><div class="scroll"><table><thead><tr><th>Case</th><th>Parent pair</th><th>Child pair</th><th>Interval cost c</th><th>Pair bound L(Q)</th><th>Certified upper bound</th></tr></thead><tbody id="rows"></tbody></table></div><p class="note">The pair dynamic program leaves exactly these twelve census entries above 346. All others already have pair bound at most 346. Distinct absolute determinant spectra separate the two parent representatives with pair (520,26).</p></section>
<footer>The sharp constant remains unknown (existing lower bound: 22). Hodge F2/F3′ and GSC remain open. The independent verifier checks geometry and census coverage; it does not reconstruct the full classification histogram. No new Lean proof, journal acceptance or DOI is asserted. Coordinates: Kreuzer–Skarke / calabi-yau-data, CC BY-SA 4.0. Geometry and numerical claims are read from the embedded retained certificate bundle.</footer></main>
<script type="application/json" id="data">__DATA__</script><script>
const bundle=JSON.parse(document.getElementById('data').textContent),data=bundle.certificates,$=id=>document.getElementById(id),canvas=$('cloud'),ctx=canvas.getContext('2d');let selected=0,angle=0,paused=matchMedia('(prefers-reduced-motion: reduce)').matches,projected=[],last=0;
const pair=v=>'('+v.join(', ')+')';
data.forEach((r,i)=>{let o=document.createElement('option');o.value=i;o.textContent=`Case ${i+1} · ${pair(r.parent_pair)}`;$('case').append(o);let tr=document.createElement('tr');tr.dataset.i=i;tr.tabIndex=0;tr.setAttribute('aria-label',`Select certificate ${i+1}`);tr.innerHTML=`<td>${String(i+1).padStart(2,'0')}</td><td>${pair(r.parent_pair)}</td><td>${pair(r.child_pair)}</td><td>${r.interval_cost}</td><td>${r.child_pair_bound}</td><td>${r.depth_upper_bound}</td>`;tr.onclick=()=>select(i);tr.onkeydown=e=>{if(e.key==='Enter')select(i)};$('rows').append(tr)});
function select(i){selected=+i;$('case').value=selected;const r=data[selected];document.querySelectorAll('tr[data-i]').forEach(tr=>tr.setAttribute('aria-selected',+tr.dataset.i===selected));$('cut').textContent=`q = (${r.cut.join(', ')}); retain x when q · x ≥ −1`;$('detail').innerHTML=`<div><b>${r.parent_pair[0]} → ${r.child_pair[0]}</b><small>primal lattice points</small></div><div><b>${r.parent_pair[1]} → ${r.child_pair[1]}</b><small>polar lattice points</small></div><div><b>${r.interval_cost}</b><small>interval cost</small></div><div><b>≤ ${r.depth_upper_bound}</b><small>${r.interval_cost} + ${r.child_pair_bound} descent steps</small></div>`;$('bar').style.width=`${r.depth_upper_bound/350*100}%`;$('barlabel').textContent=`${r.depth_upper_bound} on a 0–350 scale`;$('vertices').textContent=JSON.stringify({source:r.source,cut:r.cut,child_vertices:r.child_vertices,source_files:bundle.provenance},null,2);draw();}
function draw(){const rect=canvas.getBoundingClientRect(),dpr=devicePixelRatio||1;canvas.width=rect.width*dpr;canvas.height=rect.height*dpr;ctx.setTransform(dpr,0,0,dpr,0,0);const w=rect.width,h=rect.height;ctx.clearRect(0,0,w,h);ctx.strokeStyle='#1c2a42';ctx.lineWidth=1;for(let x=20;x<w;x+=35){ctx.beginPath();ctx.moveTo(x,0);ctx.lineTo(x,h);ctx.stroke()}for(let y=20;y<h;y+=35){ctx.beginPath();ctx.moveTo(0,y);ctx.lineTo(w,y);ctx.stroke()}const r=data[selected],kept=new Set(r.child_points.map(p=>p.join(','))),cs=Math.cos(angle),sn=Math.sin(angle),ct=Math.cos(angle*.73),st=Math.sin(angle*.73);projected=r.parent_points.map(p=>({p,keep:kept.has(p.join(',')),a:p[0]*cs+p[3]*sn,b:p[1]*ct+p[2]*st}));const xs=projected.map(p=>p.a),ys=projected.map(p=>p.b),loX=Math.min(...xs),hiX=Math.max(...xs),loY=Math.min(...ys),hiY=Math.max(...ys),scale=Math.min((w-60)/Math.max(1,hiX-loX),(h-60)/Math.max(1,hiY-loY));for(const p of projected){p.x=w/2+(p.a-(hiX+loX)/2)*scale;p.y=h/2-(p.b-(hiY+loY)/2)*scale;ctx.globalAlpha=p.keep?.85:+$('opacity').value;ctx.fillStyle=p.keep?'#62e9c8':'#ff8c9d';ctx.beginPath();ctx.arc(p.x,p.y,p.keep?2.7:2.2,0,Math.PI*2);ctx.fill()}ctx.globalAlpha=1;ctx.fillStyle='#adbbce';ctx.font='12px system-ui';ctx.fillText('4D → 2D orthogonal projection',15,h-14)}
function frame(t){if(!paused&&t-last>40){angle+=.006;last=t;draw()}requestAnimationFrame(frame)}
$('case').onchange=e=>select(e.target.value);$('next').onclick=()=>select((selected+1)%data.length);$('play').onclick=()=>{paused=!paused;$('play').textContent=paused?'Resume rotation':'Pause rotation'};$('play').textContent=paused?'Resume rotation':'Pause rotation';$('opacity').oninput=draw;canvas.onmousemove=e=>{const b=canvas.getBoundingClientRect(),x=e.clientX-b.left,y=e.clientY-b.top;let p=projected.reduce((a,p)=>Math.hypot(p.x-x,p.y-y)<Math.hypot(a.x-x,a.y-y)?p:a,projected[0]);$('hover').textContent=p&&Math.hypot(p.x-x,p.y-y)<12?`x = (${p.p.join(', ')}): ${p.keep?'retained in Q':'outside the cut'}`:'Hover over a projected point for its four integer coordinates.'};$('download').onclick=()=>{const url=URL.createObjectURL(new Blob([JSON.stringify(bundle,null,2)],{type:'application/json'})),a=document.createElement('a');a.href=url;a.download='seed_top346.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000)};addEventListener('resize',draw);select(0);requestAnimationFrame(frame);
</script></html>'''
(ROOT/'docs/seed-intervals.html').write_text(template.replace('__DATA__',json.dumps(bundle,separators=(',',':'))),encoding='utf-8')
print('Built docs/seed-intervals.html from twelve retained witnesses')
